@startuml
class Ingredient {
  +name : string
  +measuringUnit : string
  +quantityInStock : float
}

class Dish {
  +name : string
  +identifier : int
}

class Table {
  +identifier : int
  +maximumAmountOfPeople : int
}

class Meal {
  +date : date
  +startTime : time
  +endTime : time
}

class Waiter {
  +identifier : int
  +name : string
  +address : string
  +phoneNumber : string
}

class Client {
  +taxIdentificationNumber : string
  +name : string
  +address : string
}

class MealDish {
  +quantity : float
}

Ingredient "1..*" -- "1..*" Dish : composed of
"1" -- "*" MealDish : includes
"1" -- "*" MealDish : contains
Dish "1" -- "1..*" MealDish : is part of
Table "1" -- "*" Meal : takes place at
Waiter "1" -- "*" Meal : is responsible for
"0..1" -- "1" Client : consumes
@enduml

